  label: string;
  disabled?: boolean;
  onClick?: () => void;
}

types.ButtonProps:
interface ButtonProps extends BaseProps {
  variant?: ButtonVariant;
  size?: "sm" | "default" | "lg";
  disabled?: boolean;
  control?: Control;
  onClick?: () => void;
  onHover?: (hovered: boolean) => void;
}

types.CarouselItem:
interface CarouselItem {
  value: string;
  content: Child;
  label?: string;
}

types.ChartDatum:
interface ChartDatum {
  label: string;
  value: number;
  color?: string;
}

types.ComboboxOption:
interface ComboboxOption {
  value: string;
  label: string;
  keywords?: readonly string[];
  disabled?: boolean;
}

types.CommandItem:
interface CommandItem {
  value: string;
  label: string;
  keywords?: readonly string[];
  icon?: IconName;
  group?: string;
  shortcut?: string;
  disabled?: boolean;
}

types.DataGridColumn:
interface DataGridColumn<T> {
  key: string;
  header: Child;
  value?: (row: T, index: number) => unknown;
  render?: (row: T, index: number) => Child;
  width?: Style["width"];
  align?: Style["align"];
  sortable?: boolean;
  searchable?: boolean;
  compare?: (a: T, b: T) => number;
}

types.DataGridSort:
interface DataGridSort {
  column: string;
  direction: DataGridSortDirection;
}

types.DropdownMenuItem:
interface DropdownMenuItem {
  value: string;
  label: string;
  icon?: IconName;
  shortcut?: string;
  disabled?: boolean;
  checked?: boolean;
}

types.GlassMaterial:
interface GlassMaterial {
  /** Blur radius in px of what is behind the box (CSS `backdrop-filter: blur()`), 0–64. */
  blur: number;
  /** Colour saturation of the blurred backdrop; 1 leaves it, iOS uses about 1.6. */
  saturate?: number;
  /** How far in px the backdrop bends along the rounded edge (the lens), 0 for none. */
  refraction?: number;
  /** Brightness 0–1 of the rim, the edge reflections and the sheen. */
  highlight?: number;
  /** How much the flat part enlarges the backdrop, as a thick lens does: 0–0.3 (0.06 is iOS-like). */
  magnify?: number;
  /**
   * Boxes painted in one frame with the same key fuse like drops of liquid: their
   * shapes join smoothly where they come within `blend` px of each other.
   */
  merge?: string;
  /** How far apart in px two merged boxes start bridging. Default 0 (touching). */
  blend?: number;
}

types.ImageBytesSource:
interface ImageBytesSource {
  /** Encoded PNG, JPEG, WebP or SVG bytes. */
  bytes: Uint8Array;
  mediaType?: string;
  /** Stable key can reduce GPU cache churn when pixels are updated in place. */
  cacheKey?: string;
}

types.ImageErrorEvent:
interface ImageErrorEvent {
  /** The source that failed (a path or URL; empty for bytes and pixels). */
  src: string;
  message: string;
}

types.ImageRgbaSource:
interface ImageRgbaSource {
  /** Raw RGBA8 pixels in row-major order. */
  rgba: Uint8Array;
  width: number;
  height: number;
  premultiplied?: boolean;
  cacheKey?: string;
}

types.MenuBarItem:
type MenuBarItem =
  | { type: "separator" }
  | { type?: "item"; id?: string; label: string; accelerator?: string; checked?: boolean; disabled?: boolean; onSelect?: () => void; items?: MenuBarItem[] };

types.MenubarItem:
interface MenubarItem {
  value: string;
  label: string;
  disabled?: boolean;
  checked?: boolean;
  shortcut?: string;
  onSelect?: () => void;
}

types.MenubarMenu:
interface MenubarMenu {
  value: string;
  label: string;
  disabled?: boolean;
  items: MenubarItem[];
}

types.MotionTransition:
interface MotionTransition {
  /** Duration in milliseconds. Defaults to 200 when omitted. */
  duration?: number;
  /** Delay in milliseconds. Defaults to 0. */
  delay?: number;
  easing?: MotionEasing;
}

types.NavigationMenuItem:
interface NavigationMenuItem {
  value: string;
  label: string;
  disabled?: boolean;
