  label: string;
  description?: string;
  disabled?: boolean;
}

types.QuestionnaireQuestion:
interface QuestionnaireQuestion {
  id: string;
  title: string;
  description?: string;
  type: "text" | "single" | "multiple";
  options?: readonly RadioOption[];
  required?: boolean;
  placeholder?: string;
}

types.SidebarItem:
interface SidebarItem {
  value: string;
  label: string;
  icon?: IconName;
  disabled?: boolean;
  badge?: Child;
}

types.SvgNode:
type SvgNode =
  | readonly [SvgElementName, SvgAttributes]
  | readonly [SvgElementName, SvgAttributes, readonly SvgNode[]];

types.TableColumn:
interface TableColumn<T> {
  key: string;
  header: Child;
  accessor?: keyof T | ((row: T, index: number) => Child);
  render?: (row: T, index: number) => Child;
  width?: Style["width"];
  align?: Style["align"];
}

types.ToastAction:
interface ToastAction {
  label: string;
  onClick: () => void;
}

types.ToastItem:
interface ToastItem {
  id: string;
  title: string;
  description?: string;
  variant?: ToastVariant;
  action?: ToastAction;
}

types.ToggleGroupItem:
interface ToggleGroupItem {
  value: string;
